/**
 * The subset of the `codex app-server` protocol the Codex adapter uses.
 *
 * Vendored from the TypeScript bindings generated by `codex app-server generate-ts` of @openai/codex 0.169.0
 * (source: openai/codex, codex-rs/app-server-protocol, tag rust-v0.169.0; Apache-2.0). Only the types and fields
 * used here are kept; fields marked optional here may be required upstream. The wire format is newline-delimited
 * JSON-RPC 2.0 on stdio, and the server omits the `jsonrpc` field from what it sends.
 */

// Client -> server requests.
export const INITIALIZE = "initialize";
export const INITIALIZED = "initialized"; // notification
export const ACCOUNT_READ = "account/read";
export const ACCOUNT_LOGIN_START = "account/login/start";
export const THREAD_START = "thread/start";
export const TURN_START = "turn/start";
export const TURN_INTERRUPT = "turn/interrupt";
export const MCP_SERVER_STATUS_LIST = "mcpServerStatus/list";

// Server -> client requests that ask for an approval.
export const COMMAND_APPROVAL = "item/commandExecution/requestApproval";
export const FILE_CHANGE_APPROVAL = "item/fileChange/requestApproval";

// Server -> client notifications.
export const ITEM_STARTED = "item/started";
export const ITEM_COMPLETED = "item/completed";
export const AGENT_MESSAGE_DELTA = "item/agentMessage/delta";
export const COMMAND_OUTPUT_DELTA = "item/commandExecution/outputDelta";
export const COMMAND_TERMINAL_INTERACTION = "item/commandExecution/terminalInteraction";
export const TURN_STARTED = "turn/started";
export const TURN_COMPLETED = "turn/completed";
export const TOKEN_USAGE_UPDATED = "thread/tokenUsage/updated";
export const ERROR = "error";

export type ClientInfo = { name: string; title: string | null; version: string };
export type InitializeParams = { clientInfo: ClientInfo; capabilities: null };
/** `codexHome` is the absolute path of the server's $CODEX_HOME. */
export type InitializeResponse = { userAgent: string; codexHome: string; platformFamily: string; platformOs: string };

export type McpServerConnectionStatus =
  | "notStarted" | "starting" | "connected" | "authenticationRequired" | "failed" | "cancelled" | "disabled";
/** `threadId` reports that thread's connection state in `runtimeStatus`. */
export type ListMcpServerStatusParams = { threadId?: string; cursor?: string };
export type McpServerStatus = { name: string; runtimeStatus: McpServerConnectionStatus | null };
export type ListMcpServerStatusResponse = { data: McpServerStatus[]; nextCursor: string | null };

export type Account = { type: "apiKey" } | { type: "chatgpt" } | { type: string };
export type GetAccountParams = { refreshToken?: boolean };
export type GetAccountResponse = { account: Account | null; requiresOpenaiAuth: boolean };
export type LoginAccountParams = { type: "apiKey"; apiKey: string };

/** `untrusted` asks for every command not allowed by an exec-policy rule, and for every file change. */
export type AskForApproval =
  | "untrusted"
  | "on-request"
  | "never"
  | { granular: { sandbox_approval: boolean; rules: boolean; skill_approval: boolean; request_permissions: boolean; mcp_elicitations: boolean } };
export type ApprovalsReviewer = "user" | "auto_review" | "guardian_subagent";
export type SandboxMode = "read-only" | "workspace-write" | "danger-full-access";
export type SandboxPolicy =
  | { type: "dangerFullAccess" }
  | { type: "readOnly"; networkAccess: boolean }
  | { type: "externalSandbox"; networkAccess: "restricted" | "enabled" }
  | { type: "workspaceWrite"; writableRoots: string[]; networkAccess: boolean; excludeTmpdirEnvVar: boolean; excludeSlashTmp: boolean };

export type ThreadStartParams = {
  cwd: string;
  approvalPolicy: AskForApproval;
  approvalsReviewer: ApprovalsReviewer;
  sandbox: SandboxMode;
  /** Dotted config keys, applied like `-c key=value`. */
  config: Record<string, unknown>;
  ephemeral: boolean;
};
export type ThreadStartResponse = {
  thread: { id: string };
  approvalPolicy: AskForApproval;
  approvalsReviewer: ApprovalsReviewer;
  sandbox: SandboxPolicy;
};

export type UserInput = { type: "text"; text: string; text_elements: [] };
export type TurnStartParams = { threadId: string; input: UserInput[] };
export type TurnStatus = "completed" | "interrupted" | "failed" | "inProgress";
export type TurnError = { message: string; additionalDetails: string | null };
export type Turn = { id: string; status: TurnStatus; error: TurnError | null };
export type TurnStartResponse = { turn: Turn };
export type TurnInterruptParams = { threadId: string; turnId: string };

export type CommandExecutionApprovalKind = "command" | "humanCommand" | "writeStdin";
export type CommandExecutionRequestApprovalParams = {
  kind?: CommandExecutionApprovalKind;
  threadId: string;
  turnId: string;
  itemId: string;
  approvalId?: string | null;
  /** Why it asks; for `writeStdin`, the input to be written to the running command. */
  reason?: string | null;
  /** Set only when the command asks for network access. */
  networkApprovalContext?: { host: string; protocol: string } | null;
  command?: string | null;
  cwd?: string | null;
};
export type FileChangeRequestApprovalParams = {
  threadId: string;
  turnId: string;
  itemId: string;
  reason?: string | null;
  /** [UNSTABLE upstream] Asks to allow writes under this root for the rest of the session. */
  grantRoot?: string | null;
};
/**
 * The other values (`acceptForSession`, `acceptWithExecpolicyAmendment`, `applyNetworkPolicyAmendment`, `cancel`)
 * would approve more than the one action, or end the turn; the adapter sends only these two.
 */
export type ApprovalDecision = "accept" | "decline";
export type ApprovalResponse = { decision: ApprovalDecision };

export type PatchChangeKind = { type: "add" } | { type: "delete" } | { type: "update"; move_path: string | null };
export type FileUpdateChange = { path: string; kind: PatchChangeKind; diff: string };
export type ItemStatus = "inProgress" | "completed" | "failed" | "declined";

export type ThreadItem =
  | { type: "agentMessage"; id: string; text: string }
  | { type: "commandExecution"; id: string; command: string; cwd: string; status: ItemStatus; aggregatedOutput: string | null; exitCode: number | null }
  | { type: "fileChange"; id: string; changes: FileUpdateChange[]; status: ItemStatus }
  | { type: string; id: string };

/** Item-scoped notifications; a command's output and terminal input arrive only while it executes. */
export type CommandOutputDeltaNotification = { threadId: string; turnId: string; itemId: string; delta: string };
export type TerminalInteractionNotification = { threadId: string; turnId: string; itemId: string; processId: string; stdin: string };
export type ItemNotification = { item: ThreadItem; threadId: string; turnId: string };
export type AgentMessageDeltaNotification = { threadId: string; turnId: string; itemId: string; delta: string };
export type TurnStartedNotification = { threadId: string; turn: Turn };
export type TurnCompletedNotification = { threadId: string; turn: Turn };
/**
 * Cumulative token counts for the thread (`total`); upstream also sends `last` (the latest turn),
 * `modelContextWindow` and, per breakdown, `cacheWriteInputTokens`.
 */
export type TokenUsageBreakdown = {
  totalTokens: number;
  inputTokens: number;
  cachedInputTokens: number;
  outputTokens: number;
  reasoningOutputTokens: number;
};
export type TokenUsageUpdatedNotification = { threadId: string; turnId?: string; tokenUsage: { total: TokenUsageBreakdown } };
export type ErrorNotification = { error: TurnError; willRetry: boolean; threadId: string; turnId: string };
